function maxSatisfied(need: number[], size: number[]): number {
  const used = new Array(size.length).fill(false);
  const go = (i: number): number => {
    if (i === need.length) return 0;
    let best = go(i + 1); // child i gets nothing
    for (let j = 0; j < size.length; j++) {
      if (!used[j] && size[j] >= need[i]) {
        used[j] = true;
        best = Math.max(best, 1 + go(i + 1));
        used[j] = false;
      }
    }
    return best;
  };
  return go(0);
}

