class Solution:
    def maxSatisfied(self, need: List[int], size: List[int]) -> int:
        used = [False] * len(size)

        def go(i: int) -> int:
            if i == len(need):
                return 0
            best = go(i + 1)  # child i gets nothing
            for j, s in enumerate(size):
                if not used[j] and s >= need[i]:
                    used[j] = True
                    best = max(best, 1 + go(i + 1))
                    used[j] = False
            return best

        return go(0)

