function maxSatisfied(need: number[], size: number[]): number {
  need.sort((a, b) => a - b);
  size.sort((a, b) => a - b);
  let c = 0;
  for (const s of size) {
    if (c < need.length && s >= need[c]) c++;
  }
  return c;
}

